class SupportChatScreen extends ConsumerStatefulWidget{const SupportChatScreen({super.key});@override ConsumerState<SupportChatScreen>createState()=>_SupportChatScreenState();}
class _SupportChatScreenState extends ConsumerState<SupportChatScreen>{final text=TextEditingController(),scroll=ScrollController();String?threadId;List<Map<String,dynamic>>messages=[];bool loading=true,sending=false;@override void initState(){super.initState();_load();}@override void dispose(){text.dispose();scroll.dispose();super.dispose();}void _bottom(){WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:250),curve:Curves.easeOut);});}Future<void>_load()async{if(mounted)setState(()=>loading=true);try{final repo=ref.read(engagementRepositoryProvider);threadId=await repo.ensureSupportThread();messages=await repo.supportMessages(threadId!);_bottom();}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>loading=false);}}Future<void>_send()async{final body=text.text.trim();if(body.isEmpty||threadId==null||sending)return;setState(()=>sending=true);try{final repo=ref.read(engagementRepositoryProvider);await repo.sendSupportMessage(threadId!,body);text.clear();messages=await repo.supportMessages(threadId!);if(mounted)setState((){});_bottom();}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>sending=false);}}
@override Widget build(BuildContext context){final dark=Theme.of(context).brightness==Brightness.dark,scheme=Theme.of(context).colorScheme;return Scaffold(body:SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(SpikeSpacing.page,SpikeSpacing.sm,SpikeSpacing.page,SpikeSpacing.xs),child:SizedBox(height:52,child:Stack(alignment:Alignment.center,children:[Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Text('خدمة العملاء',style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),Row(mainAxisSize:MainAxisSize.min,children:[Container(width:6,height:6,decoration:const BoxDecoration(color:Colors.green,shape:BoxShape.circle)),const SizedBox(width:SpikeSpacing.xs),const Text('الدعم',style:TextStyle(fontSize:9,color:spikeMuted))])]),Align(alignment:Alignment.centerRight,child:IconButton(onPressed:()=>context.pop(),icon:const Icon(LucideIcons.arrowRight,size:22))),Align(alignment:Alignment.centerLeft,child:IconButton(onPressed:_load,icon:const Icon(LucideIcons.refreshCw,size:18))) ]))),Expanded(child:loading?const SpikeLoading():messages.isEmpty?const SpikeEmptyState(message:'ابدأ محادثتك مع الإدارة'):RefreshIndicator(onRefresh:_load,child:ListView.builder(controller:scroll,padding:SpikeSpacing.pageList,itemCount:messages.length,itemBuilder:(context,i){final m=messages[i],mine='${m['sender_role']??''}'=='customer';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Column(crossAxisAlignment:mine?CrossAxisAlignment.end:CrossAxisAlignment.start,children:[if(!mine)const Padding(padding:EdgeInsets.only(bottom:SpikeSpacing.xs),child:Text('فريق Spike',style:TextStyle(fontSize:9,color:spikeMuted,fontWeight:FontWeight.w700))),Container(constraints:const BoxConstraints(maxWidth:290),margin:const EdgeInsets.only(bottom:SpikeSpacing.sm),padding:const EdgeInsets.symmetric(horizontal:SpikeSpacing.md,vertical:SpikeSpacing.sm),decoration:BoxDecoration(color:mine?spikeRed:(dark?spikeDarkPanel:spikePanel),borderRadius:BorderRadius.only(topLeft:const Radius.circular(SpikeRadius.control),topRight:const Radius.circular(SpikeRadius.control),bottomLeft:Radius.circular(mine?SpikeRadius.control:4),bottomRight:Radius.circular(mine?4:SpikeRadius.control))),child:Text('${m['body']??''}',style:TextStyle(fontSize:12,height:1.5,color:mine?Colors.white:null)))]));}))),Container(padding:const EdgeInsets.fromLTRB(SpikeSpacing.page,SpikeSpacing.sm,SpikeSpacing.page,SpikeSpacing.sm),decoration:BoxDecoration(color:Theme.of(context).scaffoldBackgroundColor,border:Border(top:BorderSide(color:scheme.onSurface.withValues(alpha:.08)))),child:SafeArea(top:false,child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:[Expanded(child:TextField(controller:text,minLines:1,maxLines:4,textInputAction:TextInputAction.newline,decoration:const InputDecoration(hintText:'اكتب رسالتك...'))),const SizedBox(width:SpikeSpacing.sm),IconButton.filled(style:IconButton.styleFrom(backgroundColor:spikeRed,minimumSize:const Size(46,46)),onPressed:sending?null:_send,icon:sending?const SizedBox.square(dimension:17,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(LucideIcons.send,color:Colors.white,size:19))]))) ])));}}
